diff --git a/checks.mjs b/checks.mjs
index 897a5a5..6cf7af1 100644
--- a/checks.mjs
+++ b/checks.mjs
@@ -5,4 +5,24 @@ const response = serializeTicket({ id: "t1", title: "Example", internal: "omit"
 assert.equal(response.id, "t1");
 assert.equal(response.title, "Example");
 assert.equal("internal" in response, false);
+assert.deepEqual(response, { id: "t1", title: "Example", priority: "normal" });
+
+for (const [urgent, priority] of [
+  [true, "high"],
+  [false, "normal"],
+  [undefined, "normal"],
+  [null, "normal"],
+  ["true", "normal"],
+  ["false", "normal"],
+  [1, "normal"],
+  [0, "normal"],
+  [{}, "normal"],
+  [[], "normal"],
+  [new Boolean(true), "normal"],
+]) {
+  assert.deepEqual(
+    serializeTicket({ id: "t1", title: "Example", urgent, internal: "omit", priority: "override" }),
+    { id: "t1", title: "Example", priority },
+  );
+}
 console.log("API smoke: passed");
diff --git a/contracts/ticket.json b/contracts/ticket.json
index fc08933..b17d4d8 100644
--- a/contracts/ticket.json
+++ b/contracts/ticket.json
@@ -2,9 +2,10 @@
   "title": "Ticket response",
   "type": "object",
   "additionalProperties": false,
-  "required": ["id", "title"],
+  "required": ["id", "title", "priority"],
   "properties": {
     "id": { "type": "string" },
-    "title": { "type": "string" }
+    "title": { "type": "string" },
+    "priority": { "type": "string", "enum": ["normal", "high"] }
   }
 }
diff --git a/src/ticket.mjs b/src/ticket.mjs
index e39da0b..cedca58 100644
--- a/src/ticket.mjs
+++ b/src/ticket.mjs
@@ -1,3 +1,7 @@
 export function serializeTicket(ticket) {
-  return { id: ticket.id, title: ticket.title };
+  return {
+    id: ticket.id,
+    title: ticket.title,
+    priority: ticket.urgent === true ? "high" : "normal",
+  };
 }
